var SPR=[["Arboreal Curse (2014)",7,"Transmutation",["Druid"],"Action","60 ft","V, S, M","Until dispelled",0,0,"CON","60 ft, until dispelled. Constitution save or Restrained as flesh turns to bark. Three failed saves make the target a tree.","GHPG14",["Druid"]],["Blood Bond (2014)",3,"Enchantment",["Druid"],"Action","Touch","V, S, M","1 hour",0,0,"","Touch, 1 hour. Spend three Hit Dice. The target gains temporary hit points equal to the roll and you share a telepathic link.","GHPG14",["Druid"]],["Blood Rush (2014)",1,"Transmutation",["Druid","Ranger"],"Bonus Action","Self","S","Instantaneous",0,0,"","Self, instant. Spend a Hit Die and regain the roll plus your spellcasting modifier in hit points.","GHPG14",["Druid","Ranger"]],["Bloodletter (2014)",2,"Necromancy",["Cleric","Paladin","Ranger"],"Bonus Action","Touch","V, S","Up to 1 minute",1,0,"CON","Touch, 1 minute, Concentration. The next creature hit by a touched nonmagical weapon makes a Constitution save or gets a festering wound (2d6 Necrotic each turn).","GHPG14",["Cleric","Paladin","Ranger"]],["Calling Card (2014)",0,"Illusion",["Bard","Ranger","Sorcerer","Warlock","Wizard"],"Action","Touch","S, M","Until dispelled",0,0,"","Touch, until dispelled. Mark a corpse with a visible or invisible magical sign that anyone examining the body for it finds.","GHPG14",["Bard","Ranger","Sorcerer","Warlock","Wizard"]],["Circle of Scarlet (2014)",4,"Evocation",["Sorcerer","Warlock"],"Action","120 ft","V, S, M","Instantaneous",0,0,"CON","120 ft, instant. Spend four Hit Dice. A 15-ft radius, 100-ft high pillar deals Necrotic damage equal to the roll, and failing creatures lose four of their own Hit Dice too.","GHPG14",["Sorcerer","Warlock"]],["Consume Mind (2014)",4,"Necromancy",["Cleric","Warlock","Wizard"],"Action","Self","V, S, M","1 hour",0,0,"","Self, 1 hour. Eat a bit of a corpse's brain to recall facts it knew. Ability check DC equals the corpse's Intelligence.","GHPG14",["Cleric","Warlock","Wizard"]],["Consumption (2014)",1,"Evocation",["Druid","Wizard"],"Bonus Action","60 ft","V, S, M","Up to 1 minute",1,0,"CON","60 ft, 1 minute, Concentration. Spend a Hit Die. The target loses hit points equal to the roll, and again each turn it fails a Constitution save.","GHPG14",["Druid","Wizard"]],["Creeping Death (2014)",8,"Necromancy",["Warlock","Wizard"],"Action","60 ft","S","Up to 1 minute",1,0,"CON","60 ft, 1 minute, Concentration. Spend eight Hit Dice to set a death threshold. The target dies if its hit points fall to it or below.","GHPG14",["Warlock","Wizard"]],["Creeping Touch (2014)",1,"Transmutation",["Bard","Sorcerer","Warlock","Wizard"],"Action","Self","V, S","Up to 10 minutes",1,0,"","Self, 10 minutes, Concentration. Your severed hand becomes a spider you control, see through and hear through.","GHPG14",["Bard","Sorcerer","Warlock","Wizard"]],["Crimson Lash (2014)",1,"Conjuration",["Warlock","Wizard"],"Bonus Action","Self","S","10 minutes",0,0,"","Self, 10 minutes. Spend a Hit Die. A blood whip uses that die for Necrotic damage and cuts the target's hit point maximum.","GHPG14",["Warlock","Wizard"]],["Crown of Radiance (2014)",6,"Evocation",["Bard","Cleric","Druid"],"Action","Self","V, S","10 minutes",0,0,"","Self, 10 minutes. A holy crown sheds light and deals 2d8 Radiant damage to nearby fiends, fey and undead.","GHPG14",["Bard","Cleric","Druid"]],["Dark Sacrament (2014)",4,"Evocation",["Warlock","Wizard"],"Action","Self","V, S, M","Instantaneous",0,0,"","Self, instant. Spend four Hit Dice for a melee spell attack with a jeweled dagger. A kill grants a dark blessing for 10 minutes.","GHPG14",["Warlock","Wizard"]],["Earth Worm (2014)",6,"Transmutation",["Druid","Wizard"],"Action","60 ft","V, S","Up to 1 minute",1,0,"DEX","60 ft, 1 minute, Concentration. A worm-maw of earth bites for 3d8 plus your modifier and swallows Large or smaller creatures.","GHPG14",["Druid","Wizard"]],["Fiend Flesh (2014)",2,"Transmutation",["Bard","Cleric","Sorcerer","Warlock","Wizard"],"Action","Touch","V, S, M","Up to 1 hour",1,0,"","Touch, 1 hour, Concentration. A willing creature gains Resistance to Cold, Fire and Lightning and immunity to Poison damage.","GHPG14",["Bard","Cleric","Sorcerer","Warlock","Wizard"]],["Flash Fever (2014)",3,"Necromancy",["Druid","Warlock"],"Action","60 ft","V, S, M","Up to 1 minute",1,0,"CON","60 ft, 1 minute, Concentration. Constitution save or a fever deals 1d6 Fire damage, growing by 1d6 each time you trigger it.","GHPG14",["Druid","Warlock"]],["Flense (2014)",8,"Necromancy",["Cleric","Wizard"],"Action","60 ft","V, S, M","Up to 1 minute",1,0,"CON","60 ft, 1 minute, Concentration. Ranged spell attack, then Constitution save for 8d6 Necrotic damage, repeated each turn.","GHPG14",["Cleric","Wizard"]],["Ghost Light (2014)",1,"Evocation",["Bard","Cleric","Sorcerer","Wizard"],"Action","Touch","V, S, M","1 hour",0,0,"","Touch, 1 hour. An object glows with silver light seen only by creatures you name.","GHPG14",["Bard","Cleric","Sorcerer","Wizard"]],["Heartseeker (2014)",6,"Evocation",["Sorcerer","Wizard"],"Action","300 ft","V, S, M","Up to 1 minute",1,0,"CON","300 ft, 1 minute, Concentration. Spend six Hit Dice for a blood arrow. It deals Piercing damage and widens the crit range against the target.","GHPG14",["Sorcerer","Wizard"]],["Hunter Sense (2014)",0,"Divination",["Druid","Ranger"],"Action","Touch","V, S","Up to 1 minute",1,0,"","Touch, 1 minute, Concentration. A willing target treats a d20 roll of 9 or less as 10 on Wisdom (Perception) checks.","GHPG14",["Druid","Ranger"]],["Incite Riot (2014)",5,"Enchantment",["Bard","Sorcerer","Warlock","Wizard"],"Action","30 ft","V, S, M","Up to 1 minute",1,0,"WIS","30 ft, 1 minute, Concentration. Creatures that see you make a Wisdom save or are Charmed and must brawl with the nearest creature.","GHPG14",["Bard","Sorcerer","Warlock","Wizard"]],["Investiture of Venom (2014)",5,"Transmutation",["Druid","Ranger"],"Action","Self","V, S","Up to 10 minutes",1,0,"CON","Self, 10 minutes, Concentration. Immune to Poison and the Poisoned condition. Strip poison defenses and spray a 4d6 Poison line.","GHPG14",["Druid","Ranger"]],["Little Death (2014)",5,"Necromancy",["Warlock"],"Action","Self","S, M","Up to 8 hours",1,0,"","Self, up to 8 hours, Concentration. You die and rise as a ghost. You return to life if your token stays on your corpse.","GHPG14",["Warlock"]],["Magic Mirror (2014)",5,"Abjuration",["Sorcerer"],"Reaction","Self","V, S, M","Instantaneous",0,0,"","Self, instant, reaction when targeted by a spell. Redirect the spell to a creature you see within 60 ft.","GHPG14",["Sorcerer"]],["Mortality (2014)",5,"Transmutation",["Sorcerer"],"Action","120 ft","V, S, M","Up to 1 minute",1,0,"CHA","120 ft, 1 minute, Concentration. Spend five Hit Dice. A celestial, elemental, fey, aberration or fiend loses hit points and becomes mortal.","GHPG14",["Sorcerer"]],["Neutralize Aura (2014)",1,"Abjuration",["Bard","Cleric","Paladin"],"1 minute","Touch","V, S, M","Up to 1 hour",1,0,"","Touch, 1 hour, Concentration. A willing creature cannot be magically sensed by fey, fiends, celestials or undead.","GHPG14",["Bard","Cleric","Paladin"]],["Phoenix Flames (2014)",9,"Evocation",["Cleric","Druid","Sorcerer"],"Action","Self","V, S","Instantaneous",0,0,"CON","Self, instant. Holy fire erupts in a 20-ft radius for 30d6 Radiant and exhaustion. You rise again after 10 minutes.","GHPG14",["Cleric","Druid","Sorcerer"]],["Reanimate (2014)",3,"Evocation",["Druid"],"Action","Touch","V, S, M","Instantaneous",0,0,"","Touch, instant. Spend three Hit Dice to raise a creature dead under 10 minutes with 1 hit point and a burst of vigor.","GHPG14",["Druid"]],["Red Rain (2014)",8,"Conjuration",["Cleric","Warlock"],"10 minutes","Self","V, S, M","Up to 8 hours",1,0,"WIS","Self, 8 hours, Concentration, 10-minute cast. Spend eight Hit Dice. Blood rain over 5 miles exhausts and harms creatures and blights the land.","GHPG14",["Cleric","Warlock"]],["Ride the Lightning (2014)",4,"Conjuration",["Druid","Sorcerer","Wizard"],"Action","Self","V, S, M","Instantaneous",0,0,"","Self, instant. Become lightning and teleport up to 60 ft. Creatures within 5 ft of the path take 4d6 Lightning damage.","GHPG14",["Druid","Sorcerer","Wizard"]],["Sanguine Poppet (2014)",3,"Transmutation",["Bard"],"1 minute","Touch","V, S, M","Up to 1 hour",1,0,"CON","Touch, 1 hour, Concentration, 1-minute cast. Spend three Hit Dice to animate a figure you can scout through or detonate.","GHPG14",["Bard"]],["Sanguine Shield (2014)",2,"Abjuration",["Sorcerer","Wizard"],"Action","Self","V, S","Up to 1 minute",1,0,"","Self, 1 minute, Concentration. Spend two Hit Dice. Gain 5 temporary hit points per wounded creature within 30 ft (max 15) and half cover from ranged attacks.","GHPG14",["Sorcerer","Wizard"]],["Sense Lifeblood (2014)",2,"Divination",["Druid","Ranger","Sorcerer"],"Bonus Action","Self","S","Up to 1 minute",1,0,"","Self, 1 minute, Concentration. Spend two Hit Dice. Sense kinship and who is at half hit points or less, and deal bonus damage to them.","GHPG14",["Druid","Ranger","Sorcerer"]],["Serpent Tongue (2014)",3,"Transmutation",["Warlock","Wizard"],"Bonus Action","Self","V, S","1 minute",0,0,"CON","Self, 1 minute. Your tongue becomes a serpent that bites for 1d8 Piercing and can Poison. Bonus action to repeat.","GHPG14",["Warlock","Wizard"]],["Spirit Swarm (2014)",5,"Necromancy",["Cleric","Wizard"],"Action","120 ft","V, S","Up to 1 minute",1,0,"CHA","120 ft, 1 minute, Concentration. Charisma save or 8d8 Psychic damage and Frightened of you. Half damage and no fear on a success.","GHPG14",["Cleric","Wizard"]],["Steal Immortality (2014)",9,"Transmutation",["Warlock"],"Reaction","300 ft","V, S, M","Instantaneous",0,0,"","300 ft, instant, reaction. Spend nine Hit Dice to kill a downed celestial, elemental, fey, fiend or undead and take its nature.","GHPG14",["Warlock"]],["Suffocate (2014)",3,"Conjuration",["Bard","Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S, M","Up to 1 minute",1,0,"","60 ft, 1 minute, Concentration. Spell attack to Restrain a creature with invisible hands. Creatures that need air begin to suffocate.","GHPG14",["Bard","Sorcerer","Warlock","Wizard"]],["Supernal Smite (2014)",4,"Evocation",["Paladin"],"Bonus Action","Self","V","Up to 1 minute",1,0,"","Self, 1 minute, Concentration, bonus action. Your next melee hit deals 4d6 Force damage and strips magic from the target.","GHPG14",["Paladin"]],["Theft of Vitae (2014)",2,"Transmutation",["Druid","Wizard"],"Reaction","Self","V, S","Instantaneous",0,0,"","Self, instant, reaction when a creature within 30 ft takes damage. Spend two Hit Dice to deal Necrotic damage and gain temporary hit points (max 25).","GHPG14",["Druid","Wizard"]],["Wall of Gloom (2014)",8,"Conjuration",["Bard","Wizard"],"Action","120 ft","V, S, M","10 minutes",0,0,"CHA","120 ft, 10 minutes, Concentration. A grey wall of sorrow blocks sight and incapacitates nearby creatures that fail Charisma saves.","GHPG14",["Bard","Wizard"]],["Wilting Smite (2014)",2,"Transmutation",["Paladin"],"Bonus Action","Self","V","Up to 1 minute",1,0,"","Self, 1 minute, Concentration, bonus action. Spend two Hit Dice. Your next melee hit deals extra Necrotic damage and removes resistances.","GHPG14",["Paladin"]],["Wrack (2014)",2,"Necromancy",["Cleric"],"Action","30 ft","V, S, M","Up to 1 minute",1,0,"CON","30 ft, 1 minute, Concentration. Constitution save or painful spasms halve speed and impose Disadvantage on attacks.","GHPG14",["Cleric"]]];
var SPF={"Arboreal Curse (2014)":"60 ft, until dispelled. You try to turn a creature you see into wood. If its body is flesh, it makes a Constitution save. On a success nothing happens. On a failure it is Restrained as its flesh hardens. It repeats the save at the end of each of its turns. Three successes end the spell. Three failures turn it into a tree and it is Petrified for the duration. The saves need not be consecutive, so track both counts. If the tree is burned, felled or destroyed, the creature dies. Remove curse, wish or similar magic can undo the change within one year. After a year and a day as a tree, the change is permanent.","Blood Bond (2014)":"Touch, 1 hour. You must spend three Hit Dice to cast this, or the spell fails. Roll them. The target gains that many temporary hit points. While the spell lasts you always know the target's direction and distance, you can talk to each other telepathically if it has Intelligence 3 or more, and you can target it with your spells of range Self or Touch. These benefits stop while you are on different planes. The target can end the spell at any time. If it does, it loses the remaining temporary hit points from this spell and takes Necrotic damage equal to the amount lost.\n\n**At Higher Levels.** A 5th or 6th level slot makes the duration 8 hours. A 7th or 8th level slot makes it 24 hours. A 9th level slot makes it 7 days.","Blood Rush (2014)":"Self. You must spend a Hit Die to cast this, or the spell fails. Roll it and regain hit points equal to the result plus your spellcasting ability modifier.\n\n**At Higher Levels.** For each slot level above 1st you can spend and roll one extra Hit Die.","Bloodletter (2014)":"Touch, up to 1 minute, Concentration. You touch a nonmagical weapon. The next creature it hits must make a Constitution save or take a festering wound. A creature with a festering wound takes 2d6 Necrotic damage at the start of each of its turns while the spell lasts. A creature can have only one wound at a time. Any magical healing of at least 1 hit point closes the wound and stops the damage.\n\n**At Higher Levels.** The wound's damage rises by 1d6 for each slot level above 2nd.","Calling Card (2014)":"Touch, until dispelled. You touch a corpse and leave a magical mark on it. You choose whether it appears as a visible rune or word on the flesh or stays invisible. Any creature that specifically examines the corpse for a calling card finds it automatically, whether visible or not.","Circle of Scarlet (2014)":"120 ft, instant. You must spend four Hit Dice to cast this, or the spell fails. Choose a point on the ground in range and roll the dice. A crimson pillar erupts there, 15 ft in radius and 100 ft high. Each creature inside makes a Constitution save. On a success it takes Necrotic damage equal to the total. On a failure it takes that damage and must also spend and roll four of its own Hit Dice, taking extra Necrotic damage equal to the result. You gain 5 temporary hit points for each creature that fails.","Consume Mind (2014)":"Self, 1 hour. You eat a portion of the brain of a corpse and gain its memories and knowledge. The corpse needs a brain, cannot be undead, and fails if dead more than three days without preservation. For the duration you can try to recall any important fact the creature knew, such as family history, recent events, layouts, passwords or details of its death. Each attempt is an ability check with your spellcasting modifier against a DC equal to the corpse's Intelligence score. You cannot retry the same fact.","Consumption (2014)":"60 ft, up to 1 minute, Concentration. You must spend a Hit Die to cast this, or the spell fails. Choose a creature in range and roll the die. It loses that many hit points. At the end of each of its turns it makes a Constitution save. On a failure, roll the same die again and it loses that many hit points. On a success the effect ends for it.\n\n**At Higher Levels.** Choose one more target for each slot level above 1st.","Creeping Death (2014)":"60 ft, up to 1 minute, Concentration. You must spend eight Hit Dice to cast this, or the spell fails. Roll and total them to set the target's creeping death threshold. While the spell lasts, the target dies at once if its current hit points are ever equal to or below that threshold. As a bonus action on each of your turns you can force the target to make a Constitution save. On a failure roll 2d6 and add it to the threshold. On a success add half the roll. After three successful saves, which need not be consecutive, the spell ends.","Creeping Touch (2014)":"Self, up to 10 minutes, Concentration. You detach your hand at the wrist and it becomes a spider. Within 100 ft you can speak to it telepathically. As an action you can see and hear through it until the start of your next turn, and you are blind and deaf to your own senses meanwhile. If the spider is killed or kept from returning, your hand is restored and you take 1d6 Psychic damage. If you order it back, it crawls to your wrist and the spell ends.","Crimson Lash (2014)":"Self, 10 minutes. You must spend a Hit Die to cast this, or the spell fails. A lash of clotted blood forms in your hand as a magic weapon until the spell ends. It is a simple weapon you are proficient with, with the light, finesse and reach properties. You can use your spellcasting modifier instead of Strength or Dexterity for its attack and damage rolls. Its damage die is the Hit Die you spent and the damage is Necrotic. Each time it damages a creature, that creature's hit point maximum drops by the damage taken.\n\n**At Higher Levels.** With a 3rd or 4th level slot you can make two attacks when you take the Attack action, if both use the lash. With a 5th level or higher slot you can make three.","Crown of Radiance (2014)":"Self, 10 minutes. A flaming crown of holy light sits on your head. Any fiend, fey or undead that moves within 20 ft of you, or starts its turn there, takes 2d8 Radiant damage. The crown sheds bright light in a 30-ft radius and dim light for another 30 ft.","Dark Sacrament (2014)":"Self, instant. You must spend four Hit Dice to cast this, or the spell fails. Make a melee spell attack with the dagger against a creature within 5 ft. On a hit, roll the spent dice plus 4d8 and deal that much Necrotic damage. If this reduces the creature to 0 hit points, it dies and you gain a dark blessing: Advantage on all saves, your size grows one category, you gain temporary hit points equal to your Constitution modifier (minimum 1) at the start of each of your turns, your weapon attacks deal 1d4 extra damage, and your Proficiency Bonus rises by 2. It ends after 10 minutes or when you drop to 0 hit points. While you have it, Radiant damage deals an extra 1d4 to you.\n\n**At Higher Levels.** The attack's damage rises by 1d8 for each slot level above 4th.","Earth Worm (2014)":"60 ft, up to 1 minute, Concentration. You shape the ground into a worm-like maw in an open spot in range. When you cast it you can make a melee spell attack against a creature within 5 ft of it. On a hit the target takes Piercing damage equal to 3d8 plus your spellcasting modifier. A Large or smaller target makes a Dexterity save or is swallowed. A swallowed creature is Blinded and Restrained, has total cover from outside, and takes 6d6 Bludgeoning damage at the start of each of your turns. On its turn it can use an action to repeat the save. On a success it is expelled and falls Prone within 10 ft. As a bonus action you can move the worm 20 ft and attack again against a creature within 5 ft.","Fiend Flesh (2014)":"Touch, up to 1 hour, Concentration. You touch a willing creature. Its skin turns red and scaly. For the duration it has Resistance to Cold, Fire and Lightning damage and is immune to Poison damage.","Flash Fever (2014)":"60 ft, up to 1 minute, Concentration. A living creature you pick in range breaks into a cold sweat and makes a Constitution save. On a success the spell ends. On a failure its fever rises and it takes 1d6 Fire damage at the start of its next turn. While the spell lasts you can use your reaction at the start of the creature's turn to make it take Fire damage again, 1d6 more each time. The creature can use its action to cool itself and repeat the save. On a success the fever breaks and the spell ends.\n\n**At Higher Levels.** The first damage rises by 1d6 for each slot level above 3rd.","Flense (2014)":"60 ft, up to 1 minute, Concentration. You peel the skin from a creature you see in range with necromantic force. Make a ranged spell attack against it. The target makes a Constitution save, taking 8d6 Necrotic damage on a failure and half on a success. On each of your turns you can use your action to force another save and repeat the damage. The spell ends if the target leaves range, drops to 0 hit points, or gains total cover from you.","Ghost Light (2014)":"Touch, 1 hour. You touch one object no larger than 10 ft in any dimension and name any number of creatures you see within 10 ft. The object sheds bright silvery light in a 20-ft radius and dim light for another 20 ft. Only the named creatures can see the light. Everyone else sees the area as usual.","Heartseeker (2014)":"300 ft, up to 1 minute, Concentration. You must spend six Hit Dice to cast this, or the spell fails. Blood leaves your body and hardens into a barbed arrow that flies at a creature in range. Make a ranged spell attack. On a hit roll the spent dice and the target takes that much Piercing damage. The arrow then burrows toward its heart. At the start of the target's next turn it makes a Constitution save. On a failure, attacks against it crit on a 19 or 20. At the start of each later turn it repeats the save, and each failure widens the crit range by 1 more. After three successes, which need not be consecutive, the spell ends. The wider range ends with the spell.","Hunter Sense (2014)":"Touch, up to 1 minute, Concentration. You heighten the senses of a willing creature. While the spell lasts, if it rolls 9 or lower on the d20 for a Wisdom (Perception) check, it treats the roll as a 10.","Incite Riot (2014)":"30 ft, up to 1 minute, Concentration. You wave a red handkerchief and pick any number of creatures in range that can see you. Each makes a Wisdom save or is Charmed by you until the spell ends or until you or your allies harm it. While Charmed this way it must use its turn to make unarmed strikes against the nearest creature other than you, or to move toward the nearest target. At the end of each of its turns it can repeat the save to end the effect on itself.","Investiture of Venom (2014)":"Self, up to 10 minutes, Concentration. Your veins turn green and your eyes weep poison. For the duration: you are immune to Poison damage and the Poisoned condition. When you pick a creature you see within 30 ft, you know if it resists or is immune to Poison or the Poisoned condition. As a bonus action you can choose a creature within 30 ft. It makes a Constitution save or loses any Poison resistance or immunity and immunity to the Poisoned condition until the end of your next turn. As an action you can spray toxins in a line 15 ft long and 5 ft wide. Each creature in it makes a Constitution save, taking 4d6 Poison damage on a failure and half on a success. A creature that fails is also Poisoned until the end of your next turn.","Little Death (2014)":"Self, up to 8 hours, Concentration. You drop to 0 hit points and die. At the start of your next turn you become a ghost in your corpse's space, using the ghost's statistics but keeping your alignment and personality. You can use only the ghost's abilities. You add your Proficiency Bonus to your ghost attack rolls and to the save DCs of your ghost abilities. The DM secretly rolls 1d8 when you cast it. After that many hours the spell ends. It ends early if you drop to 0 hit points as a ghost or choose to end it with an action. If the material component is still on your corpse, you return to life with half your hit point maximum. If not, you make death saves as normal. If your body is destroyed or ruined while the spell is active, the duration becomes indefinite and you stay a ghost until you drop to 0 hit points, are destroyed another way, or your body is hit by an effect that kills the living, such as raise dead or resurrection.","Magic Mirror (2014)":"Self, instant. You take this reaction when a spell targets you. A bubble of shimmering energy forms between you and the caster. The spell is redirected to a creature of your choice that you see within 60 ft. If the spell is 5th level or lower, you stop being a target and the chosen creature becomes one. If it is 6th level or higher, make an ability check with your spellcasting ability against DC 10 plus the spell's level. On a success the spell is redirected as above. On a failure you stay the target.","Mortality (2014)":"120 ft, up to 1 minute, Concentration. You must spend five Hit Dice to cast this, or the spell fails. Choose an aberration, celestial, elemental, fey or fiend in range. It makes a Charisma save or has its current and maximum hit points reduced by the total of the dice. For the duration, a creature that fails also loses all damage immunities and resistances, becomes a humanoid, and takes an extra 1d4 Necrotic damage each time it takes damage. If it drops to 0 hit points under the spell, the changes become permanent and it dies. Only restoring it to life and casting remove curse or similar magic reverses that.","Neutralize Aura (2014)":"Touch, up to 1 hour, Concentration. You mask the aura of a willing creature. For the duration, fey, fiends, celestials and undead cannot perceive it by magic. The spell ends if the creature attacks, casts a spell, deals damage, takes damage, or steps within 5 ft of one of those creatures.\n\n**At Higher Levels.** Target one more creature for each slot level above 1st.","Phoenix Flames (2014)":"Self, instant. You burn yourself away in a cloud of holy flames. Each creature within 20 ft makes a Constitution save, taking 30d6 Radiant damage and gaining one level of exhaustion on a failure, or half damage and no exhaustion on a success. A creature killed by this damage is incinerated. After 10 minutes you rise from the ashes where you cast it, fully restored as if by true resurrection.","Reanimate (2014)":"Touch, instant. You must spend three Hit Dice to cast this, or the spell fails. Touch a creature that died in the last 10 minutes. It returns to life with 1 hit point. Roll the spent dice and it gains that many temporary hit points. At the start of each of its turns it loses 1 of these. While it has any, it gets +2 to all ability checks, attack rolls and saves. When they are gone, it gains one level of exhaustion. The spell cannot raise a creature that died of old age or restore missing body parts.","Red Rain (2014)":"Self, up to 8 hours, Concentration, casting time 10 minutes. You must spend eight Hit Dice to cast this, or the spell fails. Over the next 1d6 x 5 minutes the sky darkens and blood rains over everything within 5 miles of you. A creature directly exposed gains one level of exhaustion every 10 minutes. Each time it gains a level this way it takes 2d10 Necrotic damage and its hit point maximum drops by the same amount until it is no longer exhausted. While it has any exhaustion from this spell it automatically fails saves against being Poisoned or diseased. Beast and plant creatures in the area make a Wisdom save or are Frightened until they spend 1 minute outside the area. Ordinary plants wither and die after 10 minutes of exposure. For each hour you keep concentrating, roll one of the spent dice. At the end, the total is the number of days before beasts willingly return and plants regrow in the area.","Ride the Lightning (2014)":"Self, instant. You turn into a bolt of lightning and teleport up to 60 ft to an open space you see. Each creature within 5 ft of the line between your start and end points takes 4d6 Lightning damage.\n\n**At Higher Levels.** The damage rises by 1d6 and the distance by 10 ft for each slot level above 4th.","Sanguine Poppet (2014)":"Touch, up to 1 hour, Concentration, casting time 1 minute. You must spend three Hit Dice to cast this, or the spell fails. You smear a creature-shaped object with your blood and it becomes your sanguine poppet. Its AC is 10 plus your Proficiency Bonus plus your spellcasting modifier, and it has 30 hit points. If it drops to 0 or is more than a mile from you, the spell ends. As a bonus action it can walk or climb 30 ft, and you see and hear through it until the start of your next turn. As an action you can make it burst in a spray of blood and end the spell. Roll the spent dice. Each creature within 30 ft makes a Constitution save, taking Necrotic damage equal to the total on a failure and half on a success.\n\n**At Higher Levels.** Spend one more Hit Die for each slot level above 3rd. The duration also rises by 1 hour per level above 3rd.","Sanguine Shield (2014)":"Self, up to 1 minute, Concentration. You must spend two Hit Dice to cast this, or the spell fails. You draw life from the wounded around you into a swirling shield of blood. You gain 5 temporary hit points for each creature within 30 ft that is below its hit point maximum, you included, up to 15. While you have them, you have half cover against ranged attacks. When the spell ends you lose any left.\n\n**At Higher Levels.** The maximum rises by 5 for every two slot levels above 2nd.","Sense Lifeblood (2014)":"Self, up to 1 minute, Concentration. You must spend two Hit Dice to cast this, or the spell fails. You sense the lifeblood of creatures you see. For the duration you can tell whether and how two or more creatures you see are related by blood. You also know whether a creature's hit points are at or below half. When you damage such a creature, you roll the two spent dice as extra damage.\n\n**At Higher Levels.** A 4th or 5th level slot lets you concentrate for up to 1 hour. A 6th level or higher slot lets you concentrate for up to 8 hours.","Serpent Tongue (2014)":"Self, 1 minute. Your tongue becomes a venomous snake. When you cast it, make a melee spell attack against a creature within 5 ft. On a hit the target takes 1d8 Piercing damage and makes a Constitution save or is Poisoned. It repeats the save at the end of each of its turns, ending the condition on a success. As a bonus action on your turn you can attack again against a creature within 5 ft.\n\n**At Higher Levels.** The damage rises by 1d8 for each slot level above 3rd.","Spirit Swarm (2014)":"120 ft, up to 1 minute, Concentration. You call spirits to avenge themselves on a creature you see in range. It makes a Charisma save. A creature with Charisma 2 or lower is immune. On a failure the target takes 8d8 Psychic damage and is Frightened of you until the spell ends. On a success it takes half damage and is not Frightened.","Steal Immortality (2014)":"300 ft, instant. You take this reaction when a celestial, elemental, fey, fiend or undead you see in range drops to 0 hit points. You must spend nine Hit Dice to cast it, or the spell fails. Roll them and note the total as your mortal hit points. The triggering creature dies at once, and is destroyed if it would normally return to its home plane. Your creature type becomes that of the dead creature. While changed you are immune to Poison damage and disease, need no food, drink or air, and resist nonmagical damage. You also gain a benefit by type. Celestial: Resistance to Radiant and Necrotic damage and a fly speed of 60 ft. Elemental: Resistance to Acid, Cold, Fire, Lightning and Thunder damage. Fey: as a bonus action on each of your turns you turn invisible until the start of your next turn or teleport up to 60 ft. Fiend: Resistance to Cold and Fire damage and a fly speed of 60 ft. Undead: immunity to Necrotic damage and to being Charmed or Frightened. You keep the type until you cast this spell again, which ends the old effects, or until you drop to 0 hit points, which returns your type to normal and your hit points to your mortal hit points.","Suffocate (2014)":"60 ft, up to 1 minute, Concentration. You form a pair of grasping hands of invisible force. Make a spell attack against a creature you see in range. On a hit it is Restrained as the hands crush its throat or equivalent. If it needs air, it starts to suffocate. A suffocating creature survives a number of rounds equal to 1 plus its Constitution modifier (minimum 1). At the start of its next turn after that, it becomes Unconscious and cannot regain hit points until it can breathe. A conscious restrained creature can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success the spell ends on it.","Supernal Smite (2014)":"Self, up to 1 minute, Concentration. The next time you hit a creature with a melee weapon attack during the spell, your weapon shatters the magic around it. The attack deals an extra 4d6 Force damage. If the creature is concentrating, its concentration breaks. Any spell of 3rd level or lower on it ends. For each spell of 4th level or higher on it, make an ability check with your spellcasting ability against DC 10 plus that spell's level. On a success the spell ends.","Theft of Vitae (2014)":"Self, instant. You take this reaction when a creature you see within 30 ft takes damage. You must spend two Hit Dice to cast it, or the spell fails. Roll them. The creature takes that much Necrotic damage. You then gain temporary hit points equal to the triggering damage plus this Necrotic damage, up to 25.\n\n**At Higher Levels.** The maximum rises by 10 for each slot level above 2nd.","Wall of Gloom (2014)":"120 ft, up to 10 minutes, Concentration. You raise a wall of swirling grey energy made of the pain of loss on a solid surface in range. It is up to 60 ft long, 10 ft high and 5 ft thick, or a circle with a 20-ft diameter, up to 20 ft high and 5 ft thick. It blocks line of sight and sheds dim light out to 100 ft. You and creatures you name when you cast it can pass through and stay near it unharmed. Another creature that moves within 20 ft of it, or starts its turn there, makes a Charisma save or is Incapacitated for a round by a flood of despair. A creature can pass through the wall, but it is draining. The first time a creature enters the wall on a turn, or ends its turn in it, it makes a Charisma save or gains one level of exhaustion.","Wilting Smite (2014)":"Self, up to 1 minute, Concentration. You must spend two Hit Dice to cast this, or the spell fails. The next time you hit a creature with a melee weapon attack during the spell, blood runs over your weapon and dries to black spores. Roll the spent dice. The attack deals that much extra Necrotic damage. The creature also loses all damage resistances until the start of your next turn.","Wrack (2014)":"30 ft, up to 1 minute, Concentration. Choose a creature you see in range. It makes a Constitution save or is wracked with muscle spasms for the duration. It has half speed and Disadvantage on attack rolls. At the end of each of its turns it makes another Wisdom save, ending the spell on itself on a success."};
var IT=[["Angelskin Armor","Armor","Rare",0,"Leather armor cut from the flayed skin of angels. While you wear it you are immune to Bludgeoning, Piercing and Slashing damage from nonmagical attacks, including nonmagical wooden or silvered weapons. Any celestial that sees the armor turns hostile to the wearer.",{"base":["Leather Armor"]}],["Ardor","Weapon","Artifact",1,"A fiend's battleaxe with a +3 bonus to attack and damage. A hit deals an extra 3d10 Necrotic damage. While holding it you are immune to the Charmed, Frightened, Paralyzed, Poisoned and Stunned conditions. As a bonus action you can let it hover in an open space within 5 ft. While you see it, a bonus action commands it to fly 50 ft and either attack once or return to your hands. If an effect targets the hovering axe, you count as holding it. It falls if you die. While it is on you, an action casts bane, banishment, bestow curse, branding smite or incendiary cloud (save DC 18). Each spell can be cast once, then not again until the next dawn. Only its celestial twin Zeal can harm it. A creature wielding Zeal can attack Ardor, which has AC 21 and 300 hit points.",{"by":"a fiend","fx":{"atk":3,"dmg":3,"condImm":["Charmed","Frightened","Paralyzed","Poisoned","Stunned"]},"base":["Battleaxe"],"xd":["Hit: +3d10 Necrotic"]}],["Armor of Zombie Flesh","Armor","Rare",1,"Hide armor tanned from an animated zombie. While you wear it your AC is 16 plus your Dexterity modifier. You are proficient with it even if you lack hide armor proficiency.",{"by":"a lich","base":["Hide Armor"]}],["Banshee Box","Wondrous Item","Uncommon",1,"An ivory music box inlaid with tiny scenes of violence. When an attuned creature opens the lid, it can mentally set any sound for the box to play, such as eerie music, a lively party or endless screaming. The sound plays until the lid closes. Closing and reopening lets you choose a new sound. You choose whether it carries in a 5-ft, 30-ft or 120-ft radius. If the attuned user goes more than 300 ft away, the lid shuts and the music stops.",{"by":"a spectre"}],["Blood Capsule","Wondrous Item","Uncommon",0,"A cylindrical flask etched with necrotic runes. Humanoid blood kept in it stays fresh for up to a year. It holds enough blood to feed a vampire for one day.",{}],["Bow of Four","Weapon","Very Rare",1,"A white bow set with a ruby, emerald, sapphire and diamond. While holding it, you can summon a magical arrow of one element with no action. Choose air, earth, fire or water each time. An arrow not fired within 1 minute dissolves. On a hit, the air arrow deals 2d8 Lightning damage, the earth arrow 2d8 magical Bludgeoning, the fire arrow 3d8 Fire and the water arrow 2d8 Cold.",{"by":"a primordial","base":["Longbow"],"xd":["Air: 2d8 Lightning. Earth: 2d8 Bludgeoning. Fire: 3d8 Fire. Water: 2d8 Cold"]}],["Cinder Coat","Armor","Very Rare",1,"A floor-length leather duster the color of dying embers. You have +1 AC while wearing it. It has 3 charges. When you hit a creature that is not at its hit point maximum, you can spend 1 charge to deal an extra 1d10 Fire damage. It regains 1d3 charges each dawn.",{"by":"a fiend","ch":[3,"1d3","dawn"],"fx":{"ac":1},"base":["Leather Armor"]}],["Crimson Mist","Wondrous Item","Uncommon",0,"A tiny bottle of prey pheromones, enough for one use. As an action, spray one target within 5 ft. The effect lasts 24 hours. A lycanthrope that fails its Lust for the Hunt save must prioritize a target affected by crimson mist over any other.",{}],["Ectoplasmic Whip","Weapon","Rare",1,"A whip of silver plasma that phases in and out of reality. You have +1 to attack and damage rolls with it. It is invisible to non-undead creatures. You have Advantage on attacks with it against creatures that cannot perceive it.",{"by":"a spectre","fx":{"atk":1,"dmg":1},"base":["Whip"]}],["Faerie Crown","Wondrous Item","Very Rare",0,"A crown of fragrant flowers that draws butterflies. It has 1d6 + 3 butterflies hovering around it. When a weapon attack would hit you, use your reaction to release one. It takes the hit instead of you and is destroyed. When all are used, the crown withers and is destroyed.",{}],["Fin Symbiote","Wondrous Item","Rare",1,"A tendril of flesh from a living aboleth. To attune, stitch it onto your skin and leave it for the whole attunement period while it bonds with your muscles. While attuned you gain +2 to your Transformation Save DC. You cannot remove it or end attunement on your own. If it is cut off, it regrows in 1d4 hours.",{"by":"an aberrant horror"}],["Funeral Mask","Wondrous Item","Uncommon",1,"A thin copper mask that molds to the face. While wearing it you can use an action to change your appearance for 1 hour, including height, weight, features, voice, hair and distinguishing marks. You can look like another race but your statistics do not change. You cannot change size or basic shape. You can change the look again with an action. While disguised, your hideous appearance is hidden. After you use it, it cannot be used again until the next dawn.",{"by":"a lich"}],["Heaven's Herald","Wondrous Item","Very Rare",0,"A golden trumpet that never dulls. As an action, a good creature can blow it for a rousing song heard 600 ft away. The blower picks up to 12 allies in the area. Each is immune to Frightened, has Advantage on Wisdom saves, and its hit point maximum and current hit points rise by 2d10. This lasts 24 hours. After use, it cannot be used again until dawn. A neutral creature gets no sound. An evil creature must make a DC 15 Dexterity save as divine fire strikes down, taking 8d6 Radiant damage on a failure or half on a success.",{"ch":[1,"1","dawn"]}],["Humble Frock","Wondrous Item","Uncommon",1,"A rough, weather-worn frock full of holes. While a seraph wears it with no other armor or clothing, it automatically succeeds on checks to hide its divine appearance.",{"by":"a seraph"}],["Hunter's Mutagen","Potion","Rare",0,"A glowing green liquid that sends your antibodies into overdrive. When you drink it, you are immune to Poison damage and disease for 1 hour. You also cannot contract curses such as lycanthropy or mummy rot during that time. When the hour ends you gain one level of exhaustion.",{}],["Iridescent Armor","Armor","Rare",0,"A breastplate forged from a giant dragonfly's carapace, with a gossamer cape. You have +1 AC while wearing it. Once per day, use an action to turn the cape into dragonfly wings. They give you a fly speed of 60 ft for 1 hour. After that, it cannot be used again until the next dawn.",{"ch":[1,"1","dawn"],"fx":{"ac":1},"base":["Breastplate"]}],["Iron Fangs","Wondrous Item","Rare",1,"Iron tooth caps inscribed with runes. If you shift into your hybrid or kindred form while wearing them, the metal grows over your teeth. Your bite attacks count as magical. You also cannot pass on lycanthropy through your bites.",{"by":"a lycanthrope"}],["Light Drinker","Weapon","Very Rare",1,"A longsword forged from one piece of black metal that drinks the light. You have +2 to attack and damage rolls with it, and it deals Cold damage instead of Slashing. While attuned you have darkvision 60 ft and see in magical darkness. As a bonus action it sheds magical darkness in a 15-ft radius with dim light for another 15 ft. While active, an action expands or shrinks the bright and dim radii by 5 ft each, up to 30 ft each and down to 10 ft each. Only antimagic field can suppress this darkness.",{"fx":{"atk":2,"dmg":2,"dark":60},"base":["Longsword"]}],["Lodestone Armor","Armor","Rare",1,"Plate armor lined with lodestone from the plane of elemental earth. While wearing it, a bonus action boosts its magnetism. Loose stone, soil and minerals cling to it, giving +1 AC and reducing your speed by 5 ft. You can use the bonus action again each round, stacking up to +5 AC and a 25-ft speed reduction. If 1 minute passes with no activation, the material falls off and both effects end.",{"by":"a primordial","base":["Plate Armor"]}],["Mortal Coil","Ring","Uncommon",1,"A ring of hundreds of rose gold wires coiled around the finger. While a spectre wears it, a bonus action makes the spectre fully corporeal. It no longer registers as undead to magic and can touch the world like a normal humanoid. While corporeal it loses the benefits of its transformation. A bonus action returns it to its true form.",{"by":"a spectre"}],["Profane Charm","Wondrous Item","Uncommon",1,"A charred feather from a fallen angel, wrapped in silver wire. While wearing it you can enter hallowed ground without triggering your hideous appearance. The detect evil and good spell and a paladin's divine sense cannot detect you as a fiend.",{"by":"a fiend"}],["Queen's Token","Wondrous Item","Legendary",0,"A plain acorn, one of a faerie queen's mightiest gifts. While holding it you can use an action to cast wish. After that, the acorn teleports back to the queen who gave it. If the wish would be a threat to her or her realm in her eyes, it fails and the caster turns into an oak tree. Only a wish cast with the queen's token can undo it.",{}],["Ring of Hidden Desire","Ring","Uncommon",1,"A rose gold band set with a heart of obsidian. While wearing it, use an action to try to learn a creature's darkest desire. Choose a creature you see. It makes a DC 13 Wisdom save. On a failure you learn the desire. On a success you learn nothing and the creature is immune to the ring for 24 hours. A creature with Intelligence 3 or lower is unaffected.",{"by":"a fiend"}],["Ring of Radiation","Ring","Uncommon",1,"A ring of braided copper wire. While you wear it, your elemental energies radiate outward. Your reach with unarmed strikes increases by 5 ft.",{"by":"a primordial"}],["Ring of Truth","Ring","Uncommon",1,"A golden band stamped with smiling humanoid faces. While attuned, you constantly emit an aura like zone of truth, in a 15-ft radius sphere centered on you.",{}],["Rod of Elemental Stasis","Rod","Rare",1,"A wooden rod with four glass spheres, each holding a small world of elemental energy. If an air, fire, earth or water elemental dies within 60 ft of you while you hold it, the elemental is absorbed into one of the four crystals. If all are full, the elemental dies normally. As an action, show the rod and free one captured elemental. It appears within 5 ft, friendly to you and your allies, rolls initiative and takes its own turns. It obeys your spoken commands with no action from you. With no command it defends itself. It stays 10 minutes, until you dismiss it, or until it is slain, then returns to its home plane.",{"by":"a primordial"}],["Rod of Ruin","Rod","Rare",1,"A rod of stacked crystal spheres filled with smoke. It has 3 charges and regains all of them at dusk. When a creature you see within 60 ft damages you while you hold it, use your reaction and 1 charge to force a DC 15 Constitution save. On a failure the creature ages 2d10 years and gains one level of exhaustion.",{"by":"a lich","ch":[3,"3","dusk"]}],["Rod of the Pack Master","Rod","Very Rare",1,"A driftwood rod carved with wolves and bears. While holding it, choose any number of willing creatures you see within 30 ft. You can hold it in your teeth, and it works in hybrid or kindred form. Each target becomes a wolf or a bear, depending on your lycanthrope heritage. It lasts 24 hours for each target, until you end it, or until the target drops to 0 hit points or dies. The target uses the beast's statistics but keeps its alignment, Intelligence, Wisdom and Charisma. It takes the beast's hit points and returns to its earlier hit points when it reverts. Excess damage from dropping to 0 carries over to the normal form without knocking it out unless that damage would drop the normal form to 0. The creature is limited to what its form can do and cannot speak or cast spells. Its gear melds into the new form.",{"by":"a lycanthrope"}],["Second Skin","Armor","Rare",1,"A harness woven from the hides of slain lycanthropes. In your hybrid form, it bonds to your flesh like a second pelt and your AC becomes 18. This replaces your usual Transformation AC. While wearing it you have Disadvantage on Charisma checks to interact with other lycanthropes.",{"by":"a lycanthrope","base":["Hide Armor"]}],["Seeing Glass","Wondrous Item","Very Rare",0,"An ornate silver hand mirror with a pattern of withered roses. Its reflection shows the true form of any creature in it, as if by true seeing. You can see invisible creatures, the true form of shapechangers, and the true face of creatures hiding their hideous appearance. If turned on a vampire, the glass shatters and is destroyed.",{}],["Staff of the Sorcerer King","Staff","Legendary",1,"An ebony staff with a bronze spear tip and blades carved as a winged scarab. It works as a magic spear with +2 to attack and damage rolls. You are proficient with it while attuned. You have +2 to spell attack rolls while holding it. Humanoids have Disadvantage on saves against your spells while you are attuned. You have Advantage on saves against spells that target only you. The staff is cursed and attunement passes the curse to you. Until remove curse or similar magic breaks it, you will not part with the staff and keep it within reach. You have Disadvantage on attack rolls with other weapons. Each midnight while attuned you must make a DC 17 Constitution save. On a failure your hit point maximum drops by 10 unless you are undead. Only wish restores it. If your maximum reaches 0, you die and rise as a wight.",{"by":"a spellcaster","fx":{"atk":2,"dmg":2},"base":["Spear"]}],["Stalk Symbiote","Wondrous Item","Uncommon",1,"A tendril of flesh from a living aberration. To attune, stitch it onto your scalp and leave it for the attunement period while it bonds with your brain. While attuned you have Advantage on Wisdom (Perception) checks, and you and allies within 30 ft cannot be surprised unless incapacitated by something other than nonmagical sleep. You cannot remove it or end attunement on your own. If it is cut off, it regrows in 1d4 hours.",{"by":"an aberrant horror"}],["Star Metal Ring","Ring","Rare",1,"A heavy steel ring set with a chunk of shimmering star metal. While you wear it, your limbs are crusted with iridescent star metal. All your unarmed strikes deal magical damage.",{"by":"an aberrant horror"}],["Stitching Needle","Wondrous Item","Rare",0,"A black iron needle that pierces skin easily. If a creature's mouth is sewn shut with it, it cannot speak or cast spells with verbal components. It gains telepathy out to 60 ft. A creature you speak to this way does not need a shared language but must understand at least one. A creature without telepathy can receive and reply but cannot start a conversation with you. Sewing a willing, unconscious or incapacitated creature takes 10 minutes. Removing the stitches takes 1 minute.",{}],["Straitjacket","Wondrous Item","Uncommon",1,"A stained grey jacket with arms that reach the floor and dozens of straps. While an aberrant horror wears it, it rolls twice on the Unstable Mutations table and chooses the result. It takes 10 minutes to don or doff. A creature wearing it has Disadvantage on attack rolls.",{"by":"an aberrant horror"}],["Sun Shades","Wondrous Item","Uncommon",0,"Black leather goggles with cloudy glass that fully hide the eyes. While wearing them you do not have Disadvantage on attack rolls and ability checks made in sunlight. You also cannot see in complete darkness while wearing them, even with darkvision.",{}],["Toadstool Toddy","Potion","Uncommon",0,"A fizzy fuchsia drink that tastes of autumn rain, distilled from faerie magic. A fey who drinks it can last 3 extra days in an urban environment without exhaustion or rest penalties.",{}],["Wand of the Poltergeist","Wand","Very Rare",1,"A wand of twisted dark and white wood topped with a screaming skull. It has 7 charges. With it in hand, use an action to cast shatter (1 charge), major image (3 charges) or animate objects (4 charges) with no components. The save DC is your Transformation DC. It regains 1d6 + 1 charges each dusk. If you spend the last charge, roll a d20. On a 20 the wand explodes into splinters and is destroyed.",{"by":"a spectre","ch":[7,"1d6+1","dusk"]}],["Watcher's Candle","Wondrous Item","Uncommon",0,"A black taper that cannot be lit by hand. When a celestial, fiend, undead or fey comes within 120 ft, it lights with a purple flame and burns for 1 hour, after which it cannot be used again. It does not work wrapped in packaging or stowed in a container.",{}],["Zeal","Weapon","Artifact",1,"A seraph's warhammer with a +3 bonus to attack and damage. A hit deals an extra 3d10 Radiant damage. While holding it you are immune to the Charmed, Frightened, Paralyzed, Poisoned and Stunned conditions. As a bonus action you can let it hover in an open space within 5 ft. While you see it, a bonus action commands it to fly 50 ft and either attack once or return to your hands. If an effect targets the hovering hammer, you count as holding it. It falls if you die. While it is on you, an action casts banishment, branding smite, beacon of hope, earthquake or heroism (save DC 18). Each spell can be cast once, then not again until the next dawn. Only its fiendish twin Ardor can harm it. A creature wielding Ardor can attack Zeal, which has AC 21 and 300 hit points.",{"by":"a seraph","fx":{"atk":3,"dmg":3,"condImm":["Charmed","Frightened","Paralyzed","Poisoned","Stunned"]},"base":["Warhammer"],"xd":["Hit: +3d10 Radiant"]}]];
